package org.eclipse.rdf4j.query.algebra.evaluation.function.aggregate.ext;

import java.math.BigInteger;

import org.apache.datasketches.hll.HllSketch;
import org.eclipse.rdf4j.common.annotation.Experimental;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.AGGF;

/**
 * agg:approxCountDistinct(x): an approximation of the number of distinct RDF terms in the group computed with a
 * HyperLogLog sketch (lgK = 12, about 1.6% relative standard error) in constant memory.
 */
@Experimental
public class ApproxCountDistinctAggregateFactory extends AbstractUnaryAggregateFactory {

	@Override
	public String getIri() {
		return AGGF.approxCountDistinct.stringValue();
	}

	@Override
	public ExtensionCollector getCollector() {
		return new ExtensionCollector() {
			private final HllSketch sketch = new HllSketch(12);

			@Override
			public void add(Value value) {
				sketch.update(value.toString());
			}

			@Override
			protected Value computeValue() {
				return SimpleValueFactory.getInstance()
						.createLiteral(BigInteger.valueOf(Math.round(sketch.getEstimate())));
			}
		};
	}
}
